from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2021, 1, 1)
        self.SetEndDate(2023, 12, 31)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy_symbol = self.spy.Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
                                      .Strikes(-100, 100)
                                      .Expiration(0, 365)
        )
        self.option_canonical = self.spy_option.Symbol

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.current_bucket = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_price = None

        self.held_option = None
        self.held_expiration = None
        self.exit_ticket = None
        self.expiration_block_date = None

        self.last_processed_minute = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._process_expiration_safety()
        self._process_time_stop()
        self._process_profit_target(slice)

        if self._has_option_holding() or self._entry_order_is_open():
            return

        if self.expiration_block_date == self.Time.date():
            return

        if self.spy_symbol not in slice.Bars:
            return

        bar = slice.Bars[self.spy_symbol]
        local_end = bar.EndTime.astimezone(self.TimeZone)

        if not self._is_regular_session_minute(local_end):
            return

        self._add_minute_bar(bar, local_end)

    def _is_regular_session_minute(self, local_time):
        return (
            time(9, 31) <= local_time.time() <= time(16, 0)
            and local_time.weekday() < 5
        )

    def _add_minute_bar(self, bar, local_end):
        minute = local_end.replace(second=0, microsecond=0)

        if self.last_processed_minute == minute:
            return
        self.last_processed_minute = minute

        session_start = minute.replace(hour=9, minute=31)
        if minute < session_start:
            return

        bucket_index = (minute - session_start).seconds // 300
        bucket_key = (minute.date(), bucket_index)

        if self.current_bucket is None:
            self.current_bucket = bucket_key
            self.bucket_bars = []

        if bucket_key != self.current_bucket:
            self.current_bucket = bucket_key
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) != 5:
            return

        expected = [
            session_start + timedelta(minutes=bucket_index * 5 + i)
            for i in range(5)
        ]

        actual = [
            b.EndTime.astimezone(self.TimeZone).replace(
                second=0, microsecond=0
            )
            for b in self.bucket_bars
        ]

        if actual != expected:
            self.bucket_bars = []
            return

        close = float(self.bucket_bars[-1].Close)
        end_time = expected[-1]

        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if self.fast_window.IsReady and self.slow_window.IsReady:
            previous_fast = sum(
                self.fast_window[i] for i in range(1, 6)
            ) / 5.0
            previous_slow = sum(
                self.slow_window[i] for i in range(1, 6)
            ) / 5.0

            current_fast = sum(
                self.fast_window[i] for i in range(0, 5)
            ) / 5.0
            current_slow = sum(
                self.slow_window[i] for i in range(0, 5)
            ) / 5.0

            eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)

            bullish_cross = (
                previous_fast <= previous_slow
                and current_fast > current_slow
            )

            if eligible_time and bullish_cross:
                self._try_enter(slice=None, spy_price=close)

        self.bucket_bars = []

    def _try_enter(self, slice, spy_price):
        # The active Slice is obtained from the current algorithm data state.
        # LEAN exposes the current Slice through the most recent OnData call,
        # so this method is called again through the option-chain hook below.
        self.pending_entry_price = spy_price
        self.pending_entry_time = self.Time

    def _enter_from_slice(self, slice):
        if not hasattr(self, "pending_entry_price"):
            return

        if self._has_option_holding() or self._entry_order_is_open():
            return

        if self.expiration_block_date == self.Time.date():
            return

        chain = slice.OptionChains.get(self.option_canonical)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            del self.pending_entry_price
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            del self.pending_entry_price
            return

        selected_expiry = expirations[0]
        minimum_strike = self.pending_entry_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            del self.pending_entry_price
            return

        candidates.sort(key=lambda contract: (
            float(contract.Strike),
            str(contract.Symbol)
        ))

        contract = candidates[0]
        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId
        self.entry_price = None

        self.Debug("Submitted call entry: {}".format(contract.Symbol))
        del self.pending_entry_price

    def OnOrderEvent(self, order_event):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
            and order_event.Status == OrderStatus.Filled
        ):
            self.entry_price = float(order_event.FillPrice)
            self.held_option = order_event.Symbol
            self.held_expiration = self.Securities[
                self.held_option
            ].Symbol.ID.Date.date()

            self.Debug(
                "Call entry filled: {} at {:.4f}".format(
                    self.held_option, self.entry_price
                )
            )
            self.entry_ticket = None
            self.entry_order_id = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment handled.")
            if self.Portfolio[self.spy_symbol].Invested:
                self.MarketOrder(
                    self.spy_symbol,
                    -self.Portfolio[self.spy_symbol].Quantity
                )

    def OnDataConsolidated(self, sender, consolidated):
        pass

    def _has_option_holding(self):
        return (
            self.held_option is not None
            and self.Portfolio[self.held_option].Invested
        )

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def _process_profit_target(self, slice):
        if not self._has_option_holding() or self.entry_price is None:
            return

        if self.held_option not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_option]
        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50% profit target")

    def _process_time_stop(self):
        if not self._has_option_holding() or self.held_expiration is None:
            return

        prior_trading_day = self.held_expiration - timedelta(days=1)

        while not self.Securities[self.held_option].Exchange.Hours.IsDateOpen(
            prior_trading_day
        ):
            prior_trading_day -= timedelta(days=1)

        if (
            self.Time.date() == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._liquidate_option("expiration time stop")

    def _process_expiration_safety(self):
        if self.held_option is None or self.held_expiration is None:
            return

        if self.Time.date() >= self.held_expiration:
            self.expiration_block_date = self.Time.date()
            if self._has_option_holding():
                self._liquidate_option("expiration safety exit")

    def _liquidate_option(self, reason):
        if not self._has_option_holding():
            return

        if self.exit_ticket is not None:
            return

        quantity = -self.Portfolio[self.held_option].Quantity
        self.exit_ticket = self.MarketOrder(
            self.held_option,
            quantity
        )
        self.Debug(
            "Submitted option exit: {} ({})".format(
                self.held_option, reason
            )
        )

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy_symbol].Invested:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(
                self.spy_symbol,
                -self.Portfolio[self.spy_symbol].Quantity
            )
